/**
 * okena.ts — the native ↔ TypeScript binding contract.
 *
 * ┌───────────────────────────────────────────────────────────────────────┐
 * │ THIS IS A SCAFFOLD / SPEC, NOT THE REAL BINDING.                        │
 * │                                                                         │
 * │ The real implementation is GENERATED by `uniffi-bindgen-react-native`   │
 * │ (`ubrn`) from the sibling Rust crate `crates/okena-mobile-ffi` (the     │
 * │ uniffi-annotated rework of `mobile/native`). See ../../README.md.       │
 * │                                                                         │
 * │ This file declares the agreed-upon TypeScript shape of that generated   │
 * │ module: the `OkenaNative` interface plus all the record/enum types.     │
 * │ Both sides — the Rust `#[uniffi::export]` signatures and this contract  │
 * │ — must stay in sync. When `ubrn` is wired up, the generated package's   │
 * │ exported functions should satisfy `OkenaNative` structurally (this file │
 * │ becomes the typed re-export / shim over the generated module).          │
 * └───────────────────────────────────────────────────────────────────────┘
 *
 * Signature source of truth: `crates/okena-mobile-ffi/src/lib.rs` (the
 * `#[uniffi::export]` surface).
 *
 * Sync vs. async mapping (mirrors the Rust `#[frb(sync)]` / `async fn` split,
 * which `ubrn` maps to synchronous JSI host functions vs. JS Promises):
 *   - SYNC  : cheap getters on the render hot path
 *             (getVisibleCells, getVisibleCellsPacked, getCursor, isDirty,
 *              connectionStatus, getScrollInfo, selection getters, resize*).
 *   - ASYNC : anything that crosses the wire / awaits a server response
 *             (pair, sendText, sendSpecialKey, all *_action / git / service /
 *              project / layout calls, readContent).
 */

import { toAgentLifecycle, type AgentLifecycle } from './claude';

// ─────────────────────────────────────────────────────────────────────────
// Scalar / id aliases (documentation only — all are `string`/`number` at runtime)
// ─────────────────────────────────────────────────────────────────────────

/** Opaque connection id returned by `connect`. */
export type ConnId = string;
/** Opaque terminal id (from layout / state). */
export type TerminalId = string;
/** Opaque project id. */
export type ProjectId = string;
/** Opaque folder id. */
export type FolderId = string;

// ─────────────────────────────────────────────────────────────────────────
// Enums  (uniffi enums → TS string-union; ubrn emits string-tagged values)
// ─────────────────────────────────────────────────────────────────────────

/**
 * Connection status — mirrors the FFI `ConnectionStatus` enum in
 * `api/connection.rs`. `reconnecting` means an established session dropped
 * and the transport is re-dialing (`attempt` is 1-based); `connecting` is the
 * first connect (or a restarted one).
 *
 * `Error` carries a message, so this is a discriminated union rather than a
 * bare string-union.
 */
export type ConnectionStatus =
  | { kind: 'disconnected' }
  | { kind: 'connecting' }
  | { kind: 'reconnecting'; attempt: number }
  | { kind: 'connected' }
  | { kind: 'pairing' }
  | { kind: 'error'; message: string };

/** Cursor shape — mirrors FFI `CursorShape` (`api/terminal.rs`). */
export type CursorShape = 'block' | 'underline' | 'beam';

/**
 * Named special keys the remote API accepts, mirroring
 * `okena_core::keys::SpecialKey`. `sendSpecialKey` takes one of these
 * (serialized to the same JSON variant name Rust expects).
 */
export type SpecialKey =
  | 'Enter'
  | 'Escape'
  | 'Backspace'
  | 'Delete'
  | 'CtrlC'
  | 'CtrlD'
  | 'CtrlZ'
  | 'Tab'
  | 'ArrowUp'
  | 'ArrowDown'
  | 'ArrowLeft'
  | 'ArrowRight'
  | 'Home'
  | 'End'
  | 'PageUp'
  | 'PageDown';

/** Diff mode for the git diff / file-contents calls. */
export type DiffMode = 'working_tree' | 'staged';

/** Split direction for `splitTerminal`. */
export type SplitDirection = 'horizontal' | 'vertical';

// ─────────────────────────────────────────────────────────────────────────
// Records (uniffi records → TS interfaces)
// ─────────────────────────────────────────────────────────────────────────

/**
 * A single rendered terminal cell — mirrors FFI `CellData` (`api/terminal.rs`).
 *
 * NOTE: For the render hot path prefer `getVisibleCellsPacked` (see below) +
 * the `decodeCells` reader in `./cells`, which avoids marshalling thousands of
 * these objects across JSI per frame (Decision C in RN_MIGRATION.md §2).
 */
export interface CellData {
  /** The grapheme in this cell (`" "` for blank). */
  character: string;
  /** Foreground color, ARGB packed: `0xAARRGGBB`. */
  fg: number;
  /** Background color, ARGB packed: `0xAARRGGBB`. */
  bg: number;
  /** Style flags bitmask: bold|italic|underline|strikethrough|inverse|dim. See ./cells. */
  flags: number;
}

/** Cursor state — mirrors FFI `CursorState` (`api/terminal.rs`). */
export interface CursorState {
  /** 0-based column. */
  col: number;
  /** 0-based visual row. */
  row: number;
  shape: CursorShape;
  visible: boolean;
}

/** Scroll info — mirrors FFI `ScrollInfo` (`api/terminal.rs`). */
export interface ScrollInfo {
  /** Total lines in the scrollback + screen. */
  totalLines: number;
  /** Number of visible (on-screen) lines. */
  visibleLines: number;
  /** Distance scrolled back from the bottom; 0 == pinned to bottom. */
  displayOffset: number;
}

/**
 * Selection bounds in buffer coordinates — mirrors FFI `SelectionBounds`
 * (`api/terminal.rs`). Rows are `i32` Rust-side (can be negative in scrollback),
 * cols are `u16`.
 */
export interface SelectionBounds {
  startCol: number;
  /** Buffer row; may be negative (scrollback above the screen). */
  startRow: number;
  endCol: number;
  /** Buffer row; may be negative. */
  endRow: number;
}

/** Service info — mirrors FFI `ServiceInfo` (`api/state.rs`). */
export interface ServiceInfo {
  name: string;
  status: string;
  /** Terminal hosting the service, if running. */
  terminalId?: string;
  ports: number[];
  exitCode?: number;
  kind: string;
  isExtra: boolean;
}

/** AI agent status of one terminal — mirrors FFI `AgentStatusInfo` (`types.rs`). */
export interface AgentStatusInfo {
  lifecycle: AgentLifecycle;
  /** Free-form text the agent set, e.g. "running tests 3/5". */
  custom?: string;
}

/** Project info — mirrors FFI `ProjectInfo` (`api/state.rs`). */
export interface ProjectInfo {
  id: ProjectId;
  name: string;
  path: string;
  showInOverview: boolean;
  terminalIds: TerminalId[];
  /** Map terminalId → display name. */
  terminalNames: Record<TerminalId, string>;
  gitBranch?: string;
  gitLinesAdded: number;
  gitLinesRemoved: number;
  services: ServiceInfo[];
  /** Lowercased folder color name (e.g. `"blue"`). */
  folderColor: string;
  /** Parent project id when this project is a git worktree. */
  parentProjectId?: ProjectId;
  /** Worktree child ids, in the order the desktop sidebar lists them. */
  worktreeIds: ProjectId[];
  /** Per-terminal AI agent status, for terminals currently reporting one. */
  terminalAgentStatus: Record<TerminalId, AgentStatusInfo>;
  /** Pinned in the desktop sidebar (top tier of the activity order). */
  pinned: boolean;
  /**
   * Unix millis of the project's last meaningful activity (daemon-stamped on
   * focus, a finished command and a bell); `undefined` = never.
   */
  lastActivityAt?: number;
}

/** Activity signals of one mirrored terminal — mirrors FFI `TerminalActivity`. */
export interface TerminalActivity {
  terminalId: TerminalId;
  /** A BEL arrived in live output since the terminal was last marked seen. */
  bellUnseen: boolean;
  /** An OSC 9 / OSC 777 notification arrived since the terminal was last seen. */
  notificationUnseen: boolean;
  /** Milliseconds since the last live output; `undefined` when there was none. */
  lastOutputMsAgo?: number;
}

/** Folder info — mirrors FFI `FolderInfo` (`api/state.rs`). */
export interface FolderInfo {
  id: FolderId;
  name: string;
  projectIds: ProjectId[];
  /** Lowercased folder color name. */
  folderColor: string;
}

/** Fullscreen terminal info — mirrors FFI `FullscreenInfo` (`api/state.rs`). */
export interface FullscreenInfo {
  projectId: ProjectId;
  terminalId: TerminalId;
}

// ── Agent usage (mirrors `crates/okena-mobile-ffi/src/usage.rs`) ─────────

/** One history sample of a usage window. Epoch seconds, percent 0–100. */
export interface UsagePointInfo {
  recordedAt: number;
  usedPercent: number;
}

/** One rate-limit window. Timestamps are epoch seconds on the daemon's clock. */
export interface UsageWindowInfo {
  /**
   * Stable key: Claude `five_hour` / `seven_day` / `seven_day_<model>`; Codex `primary` /
   * `secondary` / `code_review`; Grok `included` / `on_demand`.
   */
  id: string;
  /** Label the desktop uses (`Session`, `Weekly`, `Rate Limit`, …). */
  label: string;
  /** `five_hour` | `weekly` | `weekly_scoped` | `code_review` | `other`. */
  kind: string;
  /** Model of a `weekly_scoped` window. */
  scopedModel?: string;
  usedPercent: number;
  windowSeconds: number;
  resetAt?: number;
  /** Scoped Claude limits: currently binding. Always true for unscoped windows. */
  active: boolean;
  /** Samples in the current window, oldest first. */
  history: UsagePointInfo[];
}

/** Claude paid usage beyond the plan (cents). */
export interface ExtraUsageInfo {
  isEnabled: boolean;
  monthlyLimitCents: number;
  usedCreditsCents: number;
  utilization: number;
}

/** Codex credit balance (USD). */
export interface UsageCreditsInfo {
  hasCredits: boolean;
  unlimited: boolean;
  balance: number;
}

export interface ResetCreditInfo {
  title: string;
  expiresAt?: number;
}

/** Codex rate-limit reset credits. */
export interface ResetCreditsInfo {
  availableCount: number;
  credits: ResetCreditInfo[];
}

/** Weighted weekly quota of the account pool, as work and as a share of a week. */
export interface PoolAmountInfo {
  /** Work time at the pool's pace, in seconds. */
  workSeconds: number;
  /** Percent of one average pool account's week. */
  accountWeekPercent: number;
}

/** The pool's soft limit: what today may use so every working day still has quota. */
export interface PoolTodayInfo {
  /** `safePerDay - used`; negative when today already used more. */
  left: PoolAmountInfo;
  /** Used since the daemon's local midnight. */
  used: PoolAmountInfo;
  safePerDay: PoolAmountInfo;
  /** What each non-working day uses, as last week. */
  offDay: PoolAmountInfo;
  /** Using more than `safePerDay` makes the pool run short at this time; unset: it only takes from later weeks. */
  runsShortAt?: number;
  /** Label of the account whose weekly reset next follows `runsShortAt`. */
  runsShortBefore?: string;
  /** At the last 24 hours' pace the pool runs out at this time; unset: it lasts the week. */
  runsOutAtRecentPace?: number;
}

/** The pool's hard limit: nonstop work until every account is blocked. */
export interface PoolNonstopInfo {
  /** `lasts` | `beyond_horizon` | `blocked` | `unknown`. */
  kind: string;
  /** `lasts`: seconds of work until every account is blocked. */
  workSeconds?: number;
  /** `beyond_horizon`: the simulated horizon in seconds. */
  horizonSeconds?: number;
  /** `blocked`: when the first account is back, if known. */
  until?: number;
}

/** The pace that converts quota into work time. */
export interface PoolPaceInfo {
  /** Work time that fills one 5h window of an average account, in seconds. */
  sessionFillSeconds: number;
  /** Percent of a week one full 5h window costs. */
  sessionWeekPercent: number;
  /** Measured from the last 7 days; `false` means defaults. */
  fromHistory: boolean;
}

/** One account of the pool. */
export interface PoolAccountInfo {
  id: string;
  label: string;
  /** `Max 20x` / `Max 5x`; unset for the base plan. */
  tier?: string;
  /** Why the proxy skips the account now (`7d limit`, `429 cooldown`). */
  blocked?: string;
  /** Weekly percent of this account used since the daemon's local midnight. */
  usedTodayPercent: number;
  /** The `five_hour` and `seven_day` windows. */
  windows: UsageWindowInfo[];
}

/** The AI proxy's Claude account pool; severity rules are on `ApiPool` in okena-core. */
export interface PoolInfo {
  today: PoolTodayInfo;
  nonstop: PoolNonstopInfo;
  pace: PoolPaceInfo;
  /** Accounts that serve requests, in pool order. */
  accounts: PoolAccountInfo[];
}

/** Usage of one provider on the daemon's machine. */
export interface ProviderUsageInfo {
  /** `claude` | `codex` | `grok` | `unknown`. */
  provider: string;
  /** `disabled` | `no_credentials` | `pending` | `ok` | `error` | `unknown`. */
  status: string;
  plan?: string;
  fetchedAt?: number;
  lastAttemptAt?: number;
  nextAttemptAt?: number;
  fetching: boolean;
  error?: string;
  consecutiveFailures: number;
  rateLimitedUntil?: number;
  windows: UsageWindowInfo[];
  extraUsage?: ExtraUsageInfo;
  credits?: UsageCreditsInfo;
  resetCredits?: ResetCreditsInfo;
  /** Grok prepaid credit balance, in the provider's credit units. */
  prepaidBalance?: number;
  /** Claude only: the AI proxy's account pool; shown instead of `windows` when set. */
  pool?: PoolInfo;
}

/** Agent usage snapshot of one server (`usage_changed`). */
export interface UsageInfo {
  providers: ProviderUsageInfo[];
  /** `0 = Monday .. 6 = Sunday`; never empty. */
  workingDays: number[];
  generatedAt: number;
}

// ─────────────────────────────────────────────────────────────────────────
// The binding contract
// ─────────────────────────────────────────────────────────────────────────

/**
 * The full native surface — one method per exported Rust FFI function.
 *
 * Naming: Rust `snake_case` fns map to camelCase here, which is also what
 * `ubrn` emits for the generated JS bindings. `connId`/`terminalId`/etc. are
 * always passed positionally (uniffi has no keyword args, unlike `frb`).
 */
export interface OkenaNative {
  // ── connection.rs ──────────────────────────────────────────────────────

  /** One-time startup init (sets up the ConnectionManager singleton). */
  initApp(): void;

  /**
   * Open a connection to a remote server, returning its conn id. If a saved
   * token is supplied, pairing is skipped. (sync — just registers + kicks off
   * the connect; status is then polled via `connectionStatus`.)
   */
  connect(
    host: string,
    port: number,
    savedToken: string | undefined,
    tls: boolean,
    pinnedCertFingerprint: string | undefined,
  ): ConnId;

  /** Current auth token for a connection, if paired. */
  getToken(connId: ConnId): string | undefined;

  /**
   * The server certificate fingerprint this connection is pinned to, if any.
   * `undefined` means no TLS identity was established, so a token obtained here
   * was accepted trust-on-first-use and must not be treated as pinned. Only
   * meaningful when {@link canReportCertFingerprint} is true.
   */
  getCertFingerprint(connId: ConnId): string | undefined;

  /**
   * Whether this binding build implements {@link getCertFingerprint}.
   *
   * Adapter-provided, NOT a Rust export: `src/generated` is gitignored, so a
   * tree built before `get_cert_fingerprint` existed keeps working with an
   * older binding. Callers must not treat a missing pin as "no pin" — that
   * would force a re-pair on every launch without buying any protection.
   */
  canReportCertFingerprint(): boolean;

  /** Pair with the server using a pairing code (async — awaits the server). */
  pair(connId: ConnId, code: string): Promise<void>;

  /** Close the WS and clean up. */
  disconnect(connId: ConnId): void;

  /** Current connection status. */
  connectionStatus(connId: ConnId): ConnectionStatus;

  /**
   * Seconds since the last WS activity (terminal output). Returns a large
   * value if the connection doesn't exist. Used for the staleness indicator.
   */
  secondsSinceActivity(connId: ConnId): number;

  /**
   * The app returned to the foreground: resume reconnect attempts and retry
   * every connection now with a fresh attempt budget; an established session
   * gets a quick liveness probe. (No-op with bindings that predate it.)
   */
  onAppForeground(): void;

  /**
   * The app went to the background: pause reconnect attempts until
   * {@link onAppForeground}. Established sessions keep running.
   */
  onAppBackground(): void;

  /**
   * Retry one connection now: skip the backoff and reset the attempt budget,
   * keeping terminals and cached state. Only meaningful when
   * {@link canReconnectNow} is true.
   */
  reconnectNow(connId: ConnId): void;

  /** Whether this binding build implements {@link reconnectNow}. Adapter-provided. */
  canReconnectNow(): boolean;

  // ── terminal.rs ────────────────────────────────────────────────────────

  /**
   * Visible grid as one record per cell. Convenient for non-hot callers; for
   * the renderer use `getVisibleCellsPacked` instead.
   */
  getVisibleCells(connId: ConnId, terminalId: TerminalId): CellData[];

  /**
   * Visible grid as a packed little-endian binary buffer — the render hot path
   * (Decision C). Layout: `cols:u16, rows:u16` header, then `cols*rows` cells
   * of 13 bytes each (`codepoint:u32, fg:u32, bg:u32, flags:u8`). Decode with
   * `decodeCells` from `./cells`.
   *
   * Implemented Rust-side as `get_visible_cells_packed` in
   * `crates/okena-mobile-ffi/src/lib.rs`; the byte format here is the contract.
   */
  getVisibleCellsPacked(connId: ConnId, terminalId: TerminalId): ArrayBuffer;

  /** Current cursor state. */
  getCursor(connId: ConnId, terminalId: TerminalId): CursorState;

  /** Scroll the display: positive = up (into scrollback), negative = down. */
  scroll(connId: ConnId, terminalId: TerminalId, delta: number): void;

  /**
   * Scroll gesture of `lines` notches at cell `col`/`row` (positive = up). Like
   * the desktop: wheel events to the app when it enabled mouse reporting,
   * otherwise the local scrollback moves.
   */
  scrollWheel(
    connId: ConnId,
    terminalId: TerminalId,
    lines: number,
    col: number,
    row: number,
  ): void;

  /** Total/visible line counts and the current display offset. */
  getScrollInfo(connId: ConnId, terminalId: TerminalId): ScrollInfo;

  /** Begin a character-level selection at the given cell. */
  startSelection(connId: ConnId, terminalId: TerminalId, col: number, row: number): void;

  /** Begin a word (semantic) selection at the given cell. */
  startWordSelection(connId: ConnId, terminalId: TerminalId, col: number, row: number): void;

  /** Extend the active selection to the given cell. */
  updateSelection(connId: ConnId, terminalId: TerminalId, col: number, row: number): void;

  /** Clear the active selection. */
  clearSelection(connId: ConnId, terminalId: TerminalId): void;

  /** The currently selected text, if any. */
  getSelectedText(connId: ConnId, terminalId: TerminalId): string | undefined;

  /** Selection bounds for rendering the highlight overlay. */
  getSelectionBounds(connId: ConnId, terminalId: TerminalId): SelectionBounds | undefined;

  /** Send raw text input (async — goes over the WS). */
  sendText(connId: ConnId, terminalId: TerminalId, text: string): Promise<void>;

  /** Resize the terminal locally AND tell the server (async semantics). */
  resizeTerminal(connId: ConnId, terminalId: TerminalId, cols: number, rows: number): void;

  /**
   * Resize ONLY the local alacritty grid — does not notify the server. Used to
   * adapt the mobile viewport to the server's size without round-tripping.
   */
  resizeLocal(connId: ConnId, terminalId: TerminalId, cols: number, rows: number): void;

  // ── state.rs ───────────────────────────────────────────────────────────

  /** All projects from the cached remote state. */
  getProjects(connId: ConnId): ProjectInfo[];

  /** The server's focused project id, if any. */
  getFocusedProjectId(connId: ConnId): ProjectId | undefined;

  /** All folders from the cached remote state. */
  getFolders(connId: ConnId): FolderInfo[];

  /** The server's project ordering. */
  getProjectOrder(connId: ConnId): ProjectId[];

  /**
   * Activity signals of every terminal the connection mirrors (the client
   * subscribes to all of them). Cheap: one call per state poll.
   */
  getTerminalActivity(connId: ConnId): TerminalActivity[];

  /** The user viewed a terminal: clear its unseen bell / notification. */
  markTerminalSeen(connId: ConnId, terminalId: TerminalId): void;

  /** The fullscreen terminal, if one is active. */
  getFullscreenTerminal(connId: ConnId): FullscreenInfo | undefined;

  /** Layout tree for a project, serialized as JSON (`ApiLayoutNode`). */
  getProjectLayoutJson(connId: ConnId, projectId: ProjectId): string | undefined;

  /** Whether a terminal has changed (output/resize/scroll/selection). Never cleared. */
  isDirty(connId: ConnId, terminalId: TerminalId): boolean;

  /** Consume the dirty flag: true once per batch of changes. Drives the repaint loop. */
  takeDirty(connId: ConnId, terminalId: TerminalId): boolean;

  /** Send a named special key (async — goes over the WS). */
  sendSpecialKey(connId: ConnId, terminalId: TerminalId, key: SpecialKey): Promise<void>;

  /** Flat list of every terminal id across all projects. */
  getAllTerminalIds(connId: ConnId): TerminalId[];

  // ── agent usage (usage.rs) ───────────────────────────────────────────────

  /** Latest Claude / Codex / Grok usage snapshot the server pushed; `undefined` before the first. */
  getUsage(connId: ConnId): UsageInfo | undefined;
  /** Changes whenever the stored snapshot changes (`0` before the first). Poll this, then `getUsage`. */
  getUsageRevision(connId: ConnId): number;
  /**
   * Ask the daemon to refetch (`provider` `claude` / `codex` / `grok`, or all when
   * `undefined`). Throttled to 60 s per provider; the result arrives as a new
   * snapshot. Resolves to whether a fetch is now running for the requested
   * provider(s): `false` means throttled, so no new result is coming.
   */
  requestUsageRefresh(connId: ConnId, provider: string | undefined): Promise<boolean>;

  // ── terminal actions (state.rs, async) ───────────────────────────────────

  createTerminal(connId: ConnId, projectId: ProjectId): Promise<void>;
  closeTerminal(connId: ConnId, projectId: ProjectId, terminalId: TerminalId): Promise<void>;
  closeTerminals(connId: ConnId, projectId: ProjectId, terminalIds: TerminalId[]): Promise<void>;
  renameTerminal(
    connId: ConnId,
    projectId: ProjectId,
    terminalId: TerminalId,
    name: string,
  ): Promise<void>;
  focusTerminal(connId: ConnId, projectId: ProjectId, terminalId: TerminalId): Promise<void>;
  toggleMinimized(connId: ConnId, projectId: ProjectId, terminalId: TerminalId): Promise<void>;
  /** Set or clear (pass `undefined`) the fullscreen terminal. */
  setFullscreen(
    connId: ConnId,
    projectId: ProjectId,
    terminalId: TerminalId | undefined,
  ): Promise<void>;
  splitTerminal(
    connId: ConnId,
    projectId: ProjectId,
    path: number[],
    direction: SplitDirection,
  ): Promise<void>;
  /** Run a command and auto-press Enter. */
  runCommand(connId: ConnId, terminalId: TerminalId, command: string): Promise<void>;
  /** Read full terminal content as text (awaits a server response). */
  readContent(connId: ConnId, terminalId: TerminalId): Promise<string>;

  // ── git actions (state.rs, async — return JSON strings) ──────────────────

  gitStatus(connId: ConnId, projectId: ProjectId): Promise<string>;
  gitDiffSummary(connId: ConnId, projectId: ProjectId): Promise<string>;
  gitDiff(connId: ConnId, projectId: ProjectId, mode: DiffMode): Promise<string>;
  gitBranches(connId: ConnId, projectId: ProjectId): Promise<string>;
  gitFileContents(
    connId: ConnId,
    projectId: ProjectId,
    filePath: string,
    mode: DiffMode,
  ): Promise<string>;

  // ── service actions (state.rs, async) ────────────────────────────────────

  startService(connId: ConnId, projectId: ProjectId, serviceName: string): Promise<void>;
  stopService(connId: ConnId, projectId: ProjectId, serviceName: string): Promise<void>;
  restartService(connId: ConnId, projectId: ProjectId, serviceName: string): Promise<void>;
  startAllServices(connId: ConnId, projectId: ProjectId): Promise<void>;
  stopAllServices(connId: ConnId, projectId: ProjectId): Promise<void>;
  reloadServices(connId: ConnId, projectId: ProjectId): Promise<void>;

  // ── project management (state.rs, async) ─────────────────────────────────

  addProject(connId: ConnId, name: string, path: string): Promise<void>;
  setProjectColor(connId: ConnId, projectId: ProjectId, color: string): Promise<void>;
  setFolderColor(connId: ConnId, folderId: FolderId, color: string): Promise<void>;
  reorderProjectInFolder(
    connId: ConnId,
    folderId: FolderId,
    projectId: ProjectId,
    newIndex: number,
  ): Promise<void>;

  // ── layout actions (state.rs, async) ─────────────────────────────────────

  updateSplitSizes(
    connId: ConnId,
    projectId: ProjectId,
    path: number[],
    sizes: number[],
  ): Promise<void>;
  addTab(connId: ConnId, projectId: ProjectId, path: number[], inGroup: boolean): Promise<void>;
  setActiveTab(connId: ConnId, projectId: ProjectId, path: number[], index: number): Promise<void>;
  moveTab(
    connId: ConnId,
    projectId: ProjectId,
    path: number[],
    fromIndex: number,
    toIndex: number,
  ): Promise<void>;
  moveTerminalToTabGroup(
    connId: ConnId,
    projectId: ProjectId,
    terminalId: TerminalId,
    targetPath: number[],
    position: number | undefined,
    targetProjectId: ProjectId | undefined,
  ): Promise<void>;
  movePaneTo(
    connId: ConnId,
    projectId: ProjectId,
    terminalId: TerminalId,
    targetProjectId: ProjectId,
    targetTerminalId: TerminalId,
    zone: string,
  ): Promise<void>;

  // ── File upload ─────────────────────────────────────────────────────────

  /**
   * Upload the file at `localPath` (a filesystem path, not a URI; at most
   * 64 MiB) to the server host; resolves to its path there.
   */
  uploadFile(connId: ConnId, localPath: string): Promise<string>;

  // ── Claude remote (lib.rs; JSON strings — parse them with ./claude) ──────

  /** Open Claude dialogs per terminal, from the cached state (sync). */
  getClaudeDialogCounts(connId: ConnId): Record<TerminalId, number>;
  /** Terminals whose `claude` is connected to Claude remote (sync). */
  getClaudeSessions(connId: ConnId): TerminalId[];
  /** JSON `ApiClaudeSession`. */
  claudeGetSession(connId: ConnId, terminalId: TerminalId): Promise<string>;
  /**
   * JSON `ApiClaudeTranscriptPage`. Cursor `0n` asks for the first page; pass
   * back the previous page's `cursor` and `session_id` for newer entries.
   * `agentId` reads that subagent's transcript.
   * (`u64` Rust-side, which ubrn maps to `bigint`.)
   */
  claudeGetTranscript(
    connId: ConnId,
    terminalId: TerminalId,
    cursor: bigint,
    sessionId: string | undefined,
    agentId: string | undefined,
  ): Promise<string>;
  /** JSON `ApiClaudeSubagentList`. */
  claudeGetSubagents(connId: ConnId, terminalId: TerminalId): Promise<string>;
  /** JSON `ApiClaudePromptResponse`; rejects with the server's reason (400 / 409). */
  claudeSendPrompt(connId: ConnId, terminalId: TerminalId, text: string): Promise<string>;
  /**
   * `decisionJson` is an `ApiClaudeDecision`. Rejects with
   * {@link CLAUDE_DIALOG_GONE_MESSAGE} when the dialog is no longer open.
   */
  claudeAnswerDialog(
    connId: ConnId,
    terminalId: TerminalId,
    dialogId: string,
    decisionJson: string,
  ): Promise<void>;
}

/** Mirrors `DIALOG_GONE_MESSAGE` in `crates/okena-mobile-ffi/src/claude.rs`. */
export const CLAUDE_DIALOG_GONE_MESSAGE = 'dialog already answered';

/**
 * The message of an error thrown by a native call. ubrn throws
 * `MobileFfiError.Action` with the Rust message under `.inner.message`; mocks
 * and JS code throw plain errors.
 */
export function nativeErrorMessage(error: unknown): string {
  if (typeof error === 'object' && error !== null && 'inner' in error) {
    const inner = error.inner;
    if (typeof inner === 'object' && inner !== null && 'message' in inner) {
      if (typeof inner.message === 'string') return inner.message;
    }
  }
  return error instanceof Error ? error.message : String(error);
}

/**
 * Resolve the real native module generated by `ubrn` into `src/generated`
 * (see `ubrn.config.yaml`). The lookup is a synchronous Metro `require` — the
 * render hot path calls the native getters synchronously, so a dynamic
 * `import()` (async) is not an option.
 *
 * The require is lazy (inside the function, not a top-level import) so that:
 *   - this typed contract and the presentational components compile/bundle
 *     before `npm run ubrn:*` has produced the module, and
 *   - tests / off-device code that inject a mock `OkenaNative` (via
 *     `configureConnectionStore` / `configureWorkspaceStore` / the `native`
 *     prop) never hit this path.
 *
 * Until the module is generated, the `require` throws and we rethrow with a
 * pointer to the generation step (see mobile/rn/README.md).
 */
/**
 * ubrn → app-contract adapters.
 *
 * ubrn 0.31 represents uniffi types in a few shapes that differ from the
 * hand-written contract above, so the boundary (`getOkenaNative`) translates:
 *   - Data-carrying enums → tagged class instances with a PascalCase `.tag`
 *     (`{ tag: 'Connected' }`; payload under `.inner`, e.g. Error →
 *     `.inner.message`). App wants `{ kind: 'lowercase' }`. → `ConnectionStatus`.
 *   - Fieldless enums → a numeric TS enum (`CursorShape.Block === 0`). App wants
 *     the lowercase string. → `getCursor().shape`.
 *   - Map-typed record fields and returns → a JS `Map`. App indexes them as
 *     plain objects. → `ProjectInfo.terminalNames` / `.terminalAgentStatus`,
 *     `getClaudeDialogCounts()`.
 * Plain-string enums (split direction, diff mode) and all other record fields
 * already match (camelCase), so they pass through untouched.
 */
function toConnectionStatus(s: {
  tag?: string;
  inner?: {message?: string; attempt?: number};
}): ConnectionStatus {
  switch (s?.tag) {
    case 'Disconnected':
      return {kind: 'disconnected'};
    case 'Connecting':
      return {kind: 'connecting'};
    case 'Reconnecting':
      return {kind: 'reconnecting', attempt: Number(s.inner?.attempt ?? 1)};
    case 'Connected':
      return {kind: 'connected'};
    case 'Pairing':
      return {kind: 'pairing'};
    case 'Error':
      return {kind: 'error', message: s.inner?.message ?? 'Unknown error'};
    default:
      return {kind: 'disconnected'};
  }
}

// Generated `CursorShape` is a numeric enum (Block=0, Underline=1, Beam=2);
// index by it to recover the app's string union.
const CURSOR_SHAPES: CursorShape[] = ['block', 'underline', 'beam'];

function toCursorState(c: {col: number; row: number; shape: number; visible: boolean}): CursorState {
  return {col: c.col, row: c.row, visible: c.visible, shape: CURSOR_SHAPES[c.shape] ?? 'block'};
}

// Generated records carry `terminalNames` / `terminalAgentStatus` as JS `Map`s
// and u64 fields as `bigint`; the app reads plain `Record`s and numbers.
// Convert and pass everything else through. Bindings generated before a field
// existed omit it, so default it.
type GenProjectInfo = Omit<
  ProjectInfo,
  'worktreeIds' | 'terminalNames' | 'terminalAgentStatus' | 'pinned' | 'lastActivityAt'
> & {
  terminalNames: unknown;
  worktreeIds?: ProjectId[];
  terminalAgentStatus?: unknown;
  pinned?: boolean;
  lastActivityAt?: bigint | number;
};

function toRecord<V>(value: unknown): Record<string, V> {
  if (value instanceof Map) return Object.fromEntries(value) as Record<string, V>;
  return (value as Record<string, V> | undefined) ?? {};
}

function mapEntries(value: unknown): Array<[unknown, unknown]> {
  if (value instanceof Map) return Array.from(value.entries());
  if (typeof value === 'object' && value !== null) return Object.entries(value);
  return [];
}

/** A generated `Map` (or plain object) → `Record`, keeping entries `parse` accepts. */
function parseRecord<V>(value: unknown, parse: (v: unknown) => V | undefined): Record<string, V> {
  const out: Record<string, V> = {};
  for (const [key, raw] of mapEntries(value)) {
    const parsed = parse(raw);
    if (typeof key === 'string' && parsed !== undefined) out[key] = parsed;
  }
  return out;
}

const asString = (v: unknown): string | undefined => (typeof v === 'string' ? v : undefined);

function parseStrings(value: unknown): string[] {
  return Array.isArray(value) ? value.filter((v): v is string => typeof v === 'string') : [];
}

const asCount = (v: unknown): number | undefined =>
  typeof v === 'number' && Number.isInteger(v) && v >= 0 ? v : undefined;

function toAgentStatusInfo(v: unknown): AgentStatusInfo | undefined {
  if (typeof v !== 'object' || v === null) return undefined;
  const lifecycle = 'lifecycle' in v ? toAgentLifecycle(v.lifecycle) : undefined;
  if (lifecycle === undefined) return undefined;
  return {lifecycle, custom: 'custom' in v ? asString(v.custom) : undefined};
}

function toProjectInfo(p: GenProjectInfo): ProjectInfo {
  return {
    ...p,
    terminalNames: toRecord<string>(p.terminalNames),
    worktreeIds: p.worktreeIds ?? [],
    terminalAgentStatus: parseRecord(p.terminalAgentStatus, toAgentStatusInfo),
    pinned: p.pinned ?? false,
    lastActivityAt: p.lastActivityAt === undefined ? undefined : Number(p.lastActivityAt),
  };
}

type GenTerminalActivity = Omit<TerminalActivity, 'lastOutputMsAgo'> & {
  lastOutputMsAgo?: bigint | number;
};

function toTerminalActivity(a: GenTerminalActivity): TerminalActivity {
  return {
    ...a,
    lastOutputMsAgo: a.lastOutputMsAgo === undefined ? undefined : Number(a.lastOutputMsAgo),
  };
}

/** Warn once per process, not once per `getOkenaNative()` caller. */
let staleBindingWarned = false;

function warnStaleBinding(): void {
  if (staleBindingWarned) return;
  staleBindingWarned = true;
  console.warn(
    'okena native bindings predate `get_cert_fingerprint`: TLS certificate ' +
      'pins cannot be read, so they are not persisted and saved tokens are ' +
      'reused unpinned. Run `npm run ubrn:android` or `npm run ubrn:ios` to ' +
      'regenerate src/generated. See mobile/rn/README.md.',
  );
}

export function getOkenaNative(): OkenaNative {
  try {
    // The local `okena-mobile-ffi` package entry (src/index.tsx) installs the
    // JSI bindings (`installRustCrate()` + `initialize()`) on first import and
    // re-exports every generated function at the top level. Most functions
    // satisfy `OkenaNative` structurally as-is; the wrapper below only overrides
    // the ones whose enum shapes need translating (see adapters above).
    const gen = require('okena-mobile-ffi');
    const pinsReadable = typeof gen.getCertFingerprint === 'function';
    if (!pinsReadable) warnStaleBinding();
    return {
      ...gen,
      connectionStatus: (connId: ConnId) =>
        toConnectionStatus(gen.connectionStatus(connId)),
      getCursor: (connId: ConnId, terminalId: TerminalId) =>
        toCursorState(gen.getCursor(connId, terminalId)),
      getProjects: (connId: ConnId) =>
        (gen.getProjects(connId) as GenProjectInfo[]).map(toProjectInfo),
      // Bindings generated before the activity fns existed: no signals.
      getTerminalActivity: (connId: ConnId) =>
        typeof gen.getTerminalActivity === 'function'
          ? (gen.getTerminalActivity(connId) as GenTerminalActivity[]).map(toTerminalActivity)
          : [],
      markTerminalSeen: (connId: ConnId, terminalId: TerminalId) => {
        if (typeof gen.markTerminalSeen === 'function') gen.markTerminalSeen(connId, terminalId);
      },
      // Bindings generated before `scroll_wheel` / `take_dirty` existed: keep
      // scrolling the local scrollback and keep the always-repaint loop.
      scrollWheel:
        typeof gen.scrollWheel === 'function'
          ? gen.scrollWheel
          : (connId: ConnId, terminalId: TerminalId, lines: number) =>
              gen.scroll(connId, terminalId, lines),
      takeDirty: typeof gen.takeDirty === 'function' ? gen.takeDirty : gen.isDirty,
      // Bindings generated before Claude remote existed: no dialogs, no sessions.
      getClaudeDialogCounts: (connId: ConnId) =>
        typeof gen.getClaudeDialogCounts === 'function'
          ? parseRecord(gen.getClaudeDialogCounts(connId), asCount)
          : {},
      getClaudeSessions: (connId: ConnId) =>
        typeof gen.getClaudeSessions === 'function'
          ? parseStrings(gen.getClaudeSessions(connId))
          : [],
      // Bindings generated before the usage API: no usage, refresh is a no-op.
      getUsage: (connId: ConnId) =>
        typeof gen.getUsage === 'function' ? (gen.getUsage(connId) as UsageInfo | undefined) : undefined,
      getUsageRevision: (connId: ConnId) =>
        typeof gen.getUsageRevision === 'function' ? (gen.getUsageRevision(connId) as number) : 0,
      requestUsageRefresh: (connId: ConnId, provider: string | undefined) =>
        typeof gen.requestUsageRefresh === 'function'
          ? (gen.requestUsageRefresh(connId, provider) as Promise<boolean>)
          : Promise.resolve(false),
      canReportCertFingerprint: () => pinsReadable,
      // Bindings generated before the lifecycle hooks existed: no-ops, and
      // "Retry now" falls back to a fresh connect.
      onAppForeground: () => {
        if (typeof gen.onAppForeground === 'function') gen.onAppForeground();
      },
      onAppBackground: () => {
        if (typeof gen.onAppBackground === 'function') gen.onAppBackground();
      },
      reconnectNow: (connId: ConnId) => {
        if (typeof gen.reconnectNow === 'function') gen.reconnectNow(connId);
      },
      canReconnectNow: () => typeof gen.reconnectNow === 'function',
      getCertFingerprint: (connId: ConnId) =>
        pinsReadable ? gen.getCertFingerprint(connId) : undefined,
    } as OkenaNative;
  } catch (e) {
    throw new Error(
      'okena native module not generated yet — run `npm run ubrn:android` or ' +
        '`npm run ubrn:ios` to cross-compile crates/okena-mobile-ffi and emit ' +
        'src/generated. See mobile/rn/README.md. Underlying error: ' +
        String(e),
    );
  }
}
